/* -------------------- Expand purchase-level items -------------------- */
purchase_items AS (
    SELECT  TO_DATE("EVENT_DATE",'YYYYMMDD')                                  AS event_date,
            DATE_TRUNC('MONTH', TO_DATE("EVENT_DATE",'YYYYMMDD'))             AS month_start,
            "USER_PSEUDO_ID"                                                  AS user_id,
            itm.value:"item_name"::string                                     AS item_name,
            COALESCE(itm.value:"quantity"::number, 1)                         AS quantity
    FROM    all_events,
            LATERAL FLATTEN(INPUT => TRY_PARSE_JSON("ITEMS")) itm
    WHERE   "EVENT_NAME" = 'purchase'
      AND   itm.value:"item_name" IS NOT NULL
),

/* --------------- Users who bought the Speckled Tee ------------------- */
tee_buyers AS (
    SELECT DISTINCT month_start, user_id
    FROM   purchase_items
    WHERE  item_name = 'Google Red Speckled Tee'
)

/* ------------- Most-purchased other products each month -------------- */
SELECT  TO_CHAR(p.month_start,'YYYY-MM')                         AS month,
        p.item_name                                              AS most_purchased_product,
        SUM(p.quantity)                                          AS total_quantity
FROM    purchase_items p
JOIN    tee_buyers t
           ON p.month_start = t.month_start
          AND p.user_id     = t.user_id
WHERE   p.item_name <> 'Google Red Speckled Tee'
GROUP BY p.month_start, p.item_name
QUALIFY  ROW_NUMBER() OVER (PARTITION BY p.month_start
                            ORDER BY SUM(p.quantity) DESC NULLS LAST) = 1
ORDER BY p.month_start;